-- scripts/production-upgrade/03-permissions.sql
--
-- Hand-run equivalent of tenant migration 012 SyncPermissionCatalogue.
-- GENERATED from src/common/constants/permissions.ts - do not edit by hand;
-- regenerate instead, or the SQL and the application will disagree.
--
-- Additive and idempotent. Inserts every catalogue code, refreshes the
-- display name and module of codes already present, grants the full
-- catalogue to ADMIN and the default set to the other system roles.
-- It never revokes, so permissions an operator added by hand survive.
--
-- Run against ONE TENANT schema. Repeat per tenant.
--   mysql -h <host> -u <user> -p <tenant_db> < 03-permissions.sql
--
-- Afterwards, record it so the migration runner does not repeat the work:
--   INSERT INTO `migrations` (`timestamp`, `name`)
--   VALUES (1700000000012, 'SyncPermissionCatalogue1700000000012');

START TRANSACTION;

-- 1. the catalogue itself (274 codes)
ON DUPLICATE KEY UPDATE
  `permission_name` = VALUES(`permission_name`),
  `module`          = VALUES(`module`);

-- 2. ADMIN holds the whole catalogue.
--    The unique key on (role_id, permission_id) makes this additive.
SELECT UUID(), r.`id`, p.`id`
  FROM `roles` r
  CROSS JOIN `permissions` p
 WHERE r.`role_code` = 'ADMIN';

-- 3. MANAGER default grants (38)
SELECT UUID(), r.`id`, p.`id`
  FROM `roles` r
  JOIN `permissions` p ON p.`permission_code` IN (
    'brands.create',
    'brands.read',
    'brands.update',
    'categories.create',
    'categories.read',
    'categories.update',
    'customers.create',
    'customers.read',
    'customers.update',
    'dashboard.analytics',
    'dashboard.view',
    'orders.create',
    'orders.read',
    'orders.update',
    'products.create',
    'products.read',
    'products.update',
    'purchase-orders.approve',
    'purchase-orders.create',
    'purchase-orders.read',
    'purchase-orders.update',
    'quotations.create',
    'quotations.read',
    'quotations.update',
    'reports.inventory',
    'reports.purchase',
    'reports.sales',
    'settings.read',
    'stock.read',
    'stock.write',
    'suppliers.create',
    'suppliers.read',
    'suppliers.update',
    'hr.attendance.read',
    'hr.employees.read',
    'hr.leave-requests.read',
    'hr.payroll.read',
    'warehouses.read'
  )
 WHERE r.`role_code` = 'MANAGER';

-- 3. SALES default grants (21)
SELECT UUID(), r.`id`, p.`id`
  FROM `roles` r
  JOIN `permissions` p ON p.`permission_code` IN (
    'brands.read',
    'categories.read',
    'customers.create',
    'customers.read',
    'customers.update',
    'dashboard.view',
    'orders.create',
    'orders.payment',
    'orders.read',
    'orders.update',
    'payments.create',
    'payments.read',
    'products.read',
    'quotations.create',
    'quotations.read',
    'quotations.send',
    'quotations.update',
    'reports.sales',
    'returns.create',
    'returns.read',
    'stock.read'
  )
 WHERE r.`role_code` = 'SALES';

-- 3. PURCHASE default grants (16)
SELECT UUID(), r.`id`, p.`id`
  FROM `roles` r
  JOIN `permissions` p ON p.`permission_code` IN (
    'brands.read',
    'categories.read',
    'dashboard.view',
    'grn.create',
    'grn.read',
    'products.read',
    'purchase-orders.create',
    'purchase-orders.read',
    'purchase-orders.update',
    'purchase-returns.create',
    'purchase-returns.read',
    'reports.purchase',
    'stock.read',
    'suppliers.create',
    'suppliers.read',
    'suppliers.update'
  )
 WHERE r.`role_code` = 'PURCHASE';

-- 3. WAREHOUSE default grants (17)
SELECT UUID(), r.`id`, p.`id`
  FROM `roles` r
  JOIN `permissions` p ON p.`permission_code` IN (
    'adjustments.create',
    'adjustments.read',
    'dashboard.view',
    'grn.create',
    'grn.read',
    'locations.create',
    'locations.read',
    'locations.update',
    'products.read',
    'reports.inventory',
    'stock.read',
    'stock.write',
    'transfers.create',
    'transfers.read',
    'transfers.receive',
    'transfers.ship',
    'warehouses.read'
  )
 WHERE r.`role_code` = 'WAREHOUSE';

COMMIT;

-- Verify: expect 274 and a non-zero grant count per role.
SELECT COUNT(*) AS catalogue_size FROM `permissions`;
SELECT r.`role_code`, COUNT(rp.`id`) AS grants
  FROM `roles` r
  LEFT JOIN `role_permissions` rp ON rp.`role_id` = r.`id`
 GROUP BY r.`role_code`
 ORDER BY r.`role_code`;
